{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Salmeterol, the closest structural analogue sharing the same phenylethanolamine core and a long lipophilic N-substituent, has an oral bioavailability of about 1% in patients, directly supporting F < 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "(R)-Salbutamol, a lower-similarity analogue with the same ethanolamine core but a small tert-butylamine substituent, has only 9% oral bioavailability due to enantioselective first-pass sulfation; this supports low F if the query's stereochemistry corresponds to the low-bioavailability enantiomer, though the long lipophilic tail makes transfer uncertain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "(S)-Salbutamol reaches 68.7% oral bioavailability in humans, providing contradictory high-F evidence, but this is weakly transferable because the query's long lipophilic dichlorobenzyl ether tail resembles salmeterol rather than the small tert-butylamine salbutamol.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence is salmeterol, a near-structural analogue with the same ethanolamine core and long lipophilic N-substituent, whose oral bioavailability is about 1%. This strongly outweighs weaker, less transferable high-F data from salbutamol enantiomers. Therefore the query is predicted to have low oral bioavailability (F < 20%).",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "Stereochemistry-specific bioavailability data for salmeterol-like analogues are lacking; the query is a single enantiomer.",
    "The effect of the 2,6-dichlorobenzyl and extra ethylene glycol ether moiety on first-pass metabolism and absorption relative to salmeterol is unknown.",
    "Salmeterol bioavailability was measured in patients with COPD/asthma, which may differ from healthy-subject oral absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

